module TopModule(
   input   clk,
   input   rst_n,

   output  reg [3:0] gray_out
);
//Gray code to binary conversion
reg  [3:0] bin_out;
wire [3:0] gray_wire;
reg [3:0] bin_add_wire;
reg count_en;

// Counter enable - increments every two clock cycles
always @(posedge clk or negedge rst_n) begin
   if(rst_n == 1'b0) begin
      count_en <= 1'b0;
   end
   else begin
      count_en <= ~count_en;
   end
end

// Gray to binary conversion
always @(posedge clk or negedge rst_n) begin
   if(rst_n == 1'b0) begin
      bin_out <= 4'b0;
   end
   else if (count_en) begin
      bin_out[3] <= gray_wire[3];
      bin_out[2] <= gray_wire[3]^gray_wire[2];
      bin_out[1] <= gray_wire[3]^gray_wire[2]^gray_wire[1];
      bin_out[0] <= gray_wire[3]^gray_wire[2]^gray_wire[1]^gray_wire[0];
   end
end

// Binary increment
always @(posedge clk or negedge rst_n) begin
   if(rst_n == 1'b0) begin
      bin_add_wire <= 4'b0;
   end
   else if (count_en) begin
      bin_add_wire <= bin_out + 1'b1;
   end
end

// Binary to gray code conversion
assign gray_wire = (bin_add_wire >> 1) ^ bin_add_wire;

// Gray code output
always @(posedge clk or negedge rst_n) begin
   if(rst_n == 1'b0) begin
      gray_out <= 4'b0;
   end
   else if (count_en) begin
      gray_out <= gray_wire;
   end
end
endmodule
